    (
        outside_service_request_id,
        line_number,
        part_id,
        package_count,
        package_summary,
        line_phase
    )
    VALUES
    (
        p_outside_service_request_id,
        p_line_number,
        p_part_id,
        p_package_count,
        p_package_summary,
        'Initialize'
    );

    SELECT LAST_INSERT_ID() AS outside_service_request_line_id;
