CREATE DEFINER=`root`@`%` PROCEDURE `sp_Volvo_PartMaster_SetActive` (IN `p_part_number` VARCHAR(20), IN `p_is_active` TINYINT(1))   BEGIN
  UPDATE volvo_masterdata
  SET
    is_active = p_is_active,
