--
-- Structure for view `view_dunnage_history`
--
DROP TABLE IF EXISTS `view_dunnage_history`;

CREATE ALGORITHM = UNDEFINED DEFINER = `root` @`%` SQL SECURITY DEFINER VIEW `view_dunnage_history` AS
SELECT
    `dl`.`load_uuid` AS `id`,
    cast(
        NULL as char(20) charset utf8mb4
    ) AS `po_number`,
    `dt`.`type_name` AS `dunnage_type`,
    `dp`.`part_id` AS `part_number`,
    group_concat(
        concat(
            `ds`.`spec_key`,
            ':',
            coalesce(
                json_unquote(`ds`.`spec_value`),
                ''
            )
        )
        order by `ds`.`spec_key` ASC separator ', '
    ) AS `specs_combined`,
    `dl`.`quantity` AS `quantity`,
    cast(`dl`.`received_date` as date) AS `created_date`,
    cast(
        `au`.`employee_number` as char(20) charset utf8mb4
    ) AS `employee_number`,
    `dl`.`created_by` AS `created_by_username`,
    `dp`.`home_location` AS `location`,
    cast(
        NULL as char(255) charset utf8mb4
    ) AS `notes`,
    'Dunnage' AS `source_module`
FROM (
        (
            (
                (
                    `dunnage_history` `dl`
                    join `dunnage_parts` `dp` on (
                        (
                            `dl`.`part_id` = `dp`.`part_id`
                        )
                    )
                )
                join `dunnage_types` `dt` on ((`dp`.`type_id` = `dt`.`id`))
            )
            left join `dunnage_specs` `ds` on (
                (
                    `dp`.`type_id` = `ds`.`type_id`
                )
            )
        )
        left join `auth_users` `au` on (
            (
                (
                    `au`.`windows_username` = `dl`.`created_by`
                )
                and (`au`.`is_active` = TRUE)
            )
        )
    )
GROUP BY
    `dl`.`load_uuid`,
    `dt`.`type_name`,
    `dp`.`part_id`,
    `dl`.`quantity`,
    `dl`.`received_date`,
    `dl`.`created_by`,
    `dp`.`home_location`,
    `au`.`employee_number`
ORDER BY `dl`.`received_date` DESC;

-- --------------------------------------------------------

--
-- Structure for view `view_receiving_history`
--
DROP TABLE IF EXISTS `view_receiving_history`;

CREATE ALGORITHM = UNDEFINED DEFINER = `root` @`%` SQL SECURITY DEFINER VIEW `view_receiving_history` AS
SELECT
    `receiving_history`.`id` AS `id`,
    `receiving_history`.`po_number` AS `po_number`,
    `receiving_history`.`po_line_number` AS `po_line_number`,
    `receiving_history`.`part_id` AS `part_id`,
    `receiving_history`.`part_description` AS `part_description`,
    `receiving_history`.`quantity` AS `quantity`,
    cast(NULL as decimal(18, 2)) AS `weight_lbs`,
    `receiving_history`.`heat` AS `heat`,
    `receiving_history`.`transaction_date` AS `transaction_date`,
    `receiving_history`.`created_at` AS `created_at`,
    `receiving_history`.`employee_number` AS `employee_number`,
    `receiving_history`.`user_id` AS `user_id`,
    `receiving_history`.`load_number` AS `load_number`,
    `receiving_history`.`initial_location` AS `initial_location`,
    `receiving_history`.`packages_per_load` AS `packages_per_load`,
    `receiving_history`.`package_type_name` AS `package_type_name`,
    `receiving_history`.`weight_per_package` AS `weight_per_package`,
    `receiving_history`.`coils_on_skid` AS `coils_on_skid`,
    `receiving_history`.`label_number` AS `label_number`,
    `receiving_history`.`vendor_name` AS `vendor_name`,
    `receiving_history`.`po_status` AS `po_status`,
    `receiving_history`.`po_due_date` AS `po_due_date`,
    `receiving_history`.`qty_ordered` AS `qty_ordered`,
    `receiving_history`.`unit_of_measure` AS `unit_of_measure`,
    `receiving_history`.`remaining_quantity` AS `remaining_quantity`,
    `receiving_history`.`is_non_po_item` AS `is_non_po_item`,
    `receiving_history`.`is_quality_hold_required` AS `is_quality_hold_required`,
    `receiving_history`.`is_quality_hold_acknowledged` AS `is_quality_hold_acknowledged`,
    `receiving_history`.`quality_hold_restriction_type` AS `quality_hold_restriction_type`,
    `receiving_history`.`part_skid_total` AS `part_skid_total`,
    NULL AS `notes`,
    'Receiving' AS `source_module`
FROM `receiving_history`
union all
select
    `receiving_label_data`.`id` AS `id`,
    `receiving_label_data`.`po_number` AS `po_number`,
    `receiving_label_data`.`po_line_number` AS `po_line_number`,
    `receiving_label_data`.`part_id` AS `part_id`,
    `receiving_label_data`.`part_description` AS `part_description`,
    `receiving_label_data`.`quantity` AS `quantity`,
    `receiving_label_data`.`weight_quantity` AS `weight_lbs`,
    `receiving_label_data`.`heat` AS `heat`,
    `receiving_label_data`.`transaction_date` AS `transaction_date`,
    coalesce(
        `receiving_label_data`.`received_date`,
        `receiving_label_data`.`created_at`
    ) AS `created_at`,
    `receiving_label_data`.`employee_number` AS `employee_number`,
    `receiving_label_data`.`user_id` AS `user_id`,
    `receiving_label_data`.`load_number` AS `load_number`,
    `receiving_label_data`.`initial_location` AS `initial_location`,
    `receiving_label_data`.`packages_per_load` AS `packages_per_load`,
    `receiving_label_data`.`package_type_name` AS `package_type_name`,
    `receiving_label_data`.`weight_per_package` AS `weight_per_package`,
    `receiving_label_data`.`coils_on_skid` AS `coils_on_skid`,
    `receiving_label_data`.`label_number` AS `label_number`,
    `receiving_label_data`.`vendor_name` AS `vendor_name`,
    `receiving_label_data`.`po_status` AS `po_status`,
    `receiving_label_data`.`po_due_date` AS `po_due_date`,
    `receiving_label_data`.`qty_ordered` AS `qty_ordered`,
    `receiving_label_data`.`unit_of_measure` AS `unit_of_measure`,
    `receiving_label_data`.`remaining_quantity` AS `remaining_quantity`,
    `receiving_label_data`.`is_non_po_item` AS `is_non_po_item`,
    `receiving_label_data`.`is_quality_hold_required` AS `is_quality_hold_required`,
    `receiving_label_data`.`is_quality_hold_acknowledged` AS `is_quality_hold_acknowledged`,
    `receiving_label_data`.`quality_hold_restriction_type` AS `quality_hold_restriction_type`,
    `receiving_label_data`.`part_skid_total` AS `part_skid_total`,
    NULL AS `notes`,
    'Receiving' AS `source_module`
from `receiving_label_data`
order by `created_at` desc, `id` desc;

