--
-- Structure for view `view_volvo_history`
--
DROP TABLE IF EXISTS `view_volvo_history`;

CREATE ALGORITHM = UNDEFINED DEFINER = `root` @`%` SQL SECURITY DEFINER VIEW `view_volvo_history` AS
SELECT
    cast(
        `vsl`.`id` as char(20) charset utf8mb4
    ) AS `id`,
    `vs`.`po_number` AS `po_number`,
    `vsl`.`part_number` AS `part_number`,
    cast(
        `vsl`.`calculated_piece_count` as decimal(10, 2)
    ) AS `quantity`,
    cast(`vs`.`created_date` as date) AS `created_date`,
    `vs`.`employee_number` AS `employee_number`,
    coalesce(
        `vsl`.`discrepancy_note`,
        `vs`.`notes`
    ) AS `notes`,
    `vs`.`shipment_number` AS `shipment_number`,
    `vs`.`receiver_number` AS `receiver_number`,
    `vs`.`status` AS `status`,
    1 AS `part_count`,
    `vsl`.`location` AS `location`,
    `vsl`.`quantity_per_skid` AS `quantity_per_skid`,
    `vsl`.`received_skid_count` AS `received_skid_count`,
    'Volvo' AS `source_module`
FROM (
        `volvo_label_data` `vs`
        join `volvo_line_data` `vsl` on (
            (
                `vs`.`id` = `vsl`.`shipment_id`
            )
        )
    )
union all
select
    cast(
        `vlnh`.`id` as char(20) charset utf8mb4
    ) AS `id`,
    `vlh`.`po_number` AS `po_number`,
    `vlnh`.`part_number` AS `part_number`,
    cast(
        `vlnh`.`calculated_piece_count` as decimal(10, 2)
    ) AS `quantity`,
    cast(`vlh`.`created_date` as date) AS `created_date`,
    `vlh`.`employee_number` AS `employee_number`,
    coalesce(
        `vlnh`.`discrepancy_note`,
        `vlh`.`notes`
    ) AS `notes`,
    `vlh`.`shipment_number` AS `shipment_number`,
    `vlh`.`receiver_number` AS `receiver_number`,
    `vlh`.`status` AS `status`,
    1 AS `part_count`,
    `vlnh`.`location` AS `location`,
    `vlnh`.`quantity_per_skid` AS `quantity_per_skid`,
    `vlnh`.`received_skid_count` AS `received_skid_count`,
    'Volvo' AS `source_module`
from (
        `volvo_label_history` `vlh`
        join `volvo_line_history` `vlnh` on (
            (
                `vlh`.`id` = `vlnh`.`shipment_history_id`
            )
        )
    )
order by `created_date` desc;

