--
-- Structure for view `view_volvo_label_data_history`
--
DROP TABLE IF EXISTS `view_volvo_label_data_history`;

CREATE ALGORITHM = UNDEFINED DEFINER = `root` @`%` SQL SECURITY DEFINER VIEW `view_volvo_label_data_history` AS
SELECT
    `s`.`id` AS `shipment_id`,
    `s`.`shipment_date` AS `shipment_date`,
    `s`.`shipment_number` AS `shipment_number`,
    `s`.`po_number` AS `po_number`,
    `s`.`receiver_number` AS `receiver_number`,
    `s`.`status` AS `status`,
    `l`.`part_number` AS `part_number`,
    `l`.`location` AS `location`,
    `l`.`received_skid_count` AS `received_skid_count`,
    `l`.`calculated_piece_count` AS `calculated_piece_count`,
    `l`.`has_discrepancy` AS `has_discrepancy`,
    `l`.`expected_skid_count` AS `expected_skid_count`,
    `l`.`discrepancy_note` AS `discrepancy_note`
FROM (
        `volvo_label_data` `s`
        left join `volvo_line_data` `l` on (
            (`s`.`id` = `l`.`shipment_id`)
        )
    )
union all
select
    `vlh`.`id` AS `shipment_id`,
    `vlh`.`shipment_date` AS `shipment_date`,
    `vlh`.`shipment_number` AS `shipment_number`,
    `vlh`.`po_number` AS `po_number`,
    `vlh`.`receiver_number` AS `receiver_number`,
    `vlh`.`status` AS `status`,
    `vlnh`.`part_number` AS `part_number`,
    `vlnh`.`location` AS `location`,
    `vlnh`.`received_skid_count` AS `received_skid_count`,
    `vlnh`.`calculated_piece_count` AS `calculated_piece_count`,
    `vlnh`.`has_discrepancy` AS `has_discrepancy`,
    `vlnh`.`expected_skid_count` AS `expected_skid_count`,
    `vlnh`.`discrepancy_note` AS `discrepancy_note`
from (
        `volvo_label_history` `vlh`
        left join `volvo_line_history` `vlnh` on (
            (
                `vlh`.`id` = `vlnh`.`shipment_history_id`
            )
        )
    )
order by
    `shipment_date` desc,
    `shipment_number` desc;

